public String generateUserQuery(String tenantId) {
    return """
        SELECT u.id, u.username, u.email
        FROM users u
        JOIN tenants t ON u.tenant_id = t.id
        WHERE t.code = '%s'
          AND u.status = 'ACTIVE'
        ORDER BY u.created_at DESC;
        """.formatted(tenantId);
}
